-- Comprehensive verification against manifest expectations

-- 1. Total row count
SELECT 'Total Rows' as metric, count(*) as actual, 600000 as expected
FROM orders_db.orders_final;

-- 2. Total amount sum (in cents)
SELECT 'Amount Sum (cents)' as metric, sum(amount_cents) as actual, 904799879 as expected
FROM orders_db.orders_final;

-- 3. Channel counts
SELECT 'Channel Counts' as verification;
SELECT channel, count(*) as count
FROM orders_db.orders_final
GROUP BY channel
ORDER BY channel;

-- Expected: api: 90005, mobile: 209269, web: 300726

-- 4. Country counts
SELECT 'Country Counts' as verification;
SELECT country, count(*) as count
FROM orders_db.orders_final
GROUP BY country
ORDER BY country;

-- Expected: AU: 24032, BR: 29982, CA: 60461, DE: 42437, FR: 36319, GB: 59515, JP: 17965, US: 329289

-- 5. Status counts
SELECT 'Status Counts' as verification;
SELECT status, count(*) as count
FROM orders_db.orders_final
GROUP BY status
ORDER BY status;

-- Expected: failed: 17898, paid: 552070, refunded: 30032

-- 6. Check for duplicates
SELECT 'Duplicate Check' as verification;
SELECT count(*) as total_orders,
       uniq(order_id) as unique_order_ids,
       (count(*) - uniq(order_id)) as potential_duplicates
FROM orders_db.orders_final;

-- 7. Check drop_promo file - should have empty promo codes
SELECT 'Drop Promo Check' as verification;
SELECT count(*) as rows_with_empty_promo,
       count(CASE WHEN promo_code != '' THEN 1 END) as rows_with_promo
FROM orders_db.orders_final
WHERE source_object LIKE '%dt=2026-01-04/hour=16%';

-- 8. Source file distribution
SELECT 'Source File Distribution' as verification;
SELECT source_object, count(*) as count
FROM orders_db.orders_final
GROUP BY source_object
ORDER BY source_object;

